#!/usr/bin/env python3
"""Build isolated ZUI partner pages with existing embedded brand fonts."""
import re,sys,json,pathlib
out=pathlib.Path(sys.argv[1]);out.mkdir(parents=True,exist_ok=True)
source=pathlib.Path(sys.argv[2]).read_text()
fonts='\n'.join(re.findall(r'@font-face\s*\{.*?\}',source,re.S))
css=fonts+'''
:root{--bg:#080b12;--surface:#121926;--fg:#f5f5f5;--muted:#a7b2c6;--blue:#3b82f6;--green:#34d399;--line:#283447;--shade:rgba(8,11,18,.72);--shadow:0 20px 60px rgba(0,0,0,.3)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font-family:Manrope,Arial,sans-serif;letter-spacing:0}a{color:inherit;text-decoration:none}h1,h2,h3{font-family:Sora,Arial,sans-serif;letter-spacing:0}p{line-height:1.7;color:var(--muted)}header{border-bottom:1px solid var(--line)}nav{max-width:1200px;margin:auto;min-height:90px;display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 32px}nav img{width:112px;height:48px;object-fit:contain}nav div{display:flex;gap:24px;align-items:center}nav a:hover,footer a:hover{color:var(--green)}.btn{display:inline-flex;align-items:center;gap:12px;border:1px solid var(--line);border-radius:6px;padding:14px 24px;font-weight:700;background:var(--surface)}.btn.primary{background:var(--blue);border-color:var(--blue)}.hero{position:relative;min-height:590px;display:flex;align-items:center;isolation:isolate}.hero>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2}.hero:after{content:'';position:absolute;inset:0;background:var(--shade);z-index:-1}.hero .inner{width:1200px;margin:auto;padding:70px 32px;display:flex;justify-content:flex-end}.hero .copy{max-width:560px}.hero .inner{justify-content:flex-start}.hero>img{object-position:70% center}.hero{min-height:540px}.hero .copy{background:none}.section .grid{gap:24px}.plan{box-shadow:none}.plan:hover{border-color:var(--green)}.plan a{display:inline-block;color:var(--green);border-top:1px solid var(--line);padding-top:20px;margin-top:14px;width:100%}.platform-grid{margin-top:30px}.platform{position:relative}.platform .badge{border-bottom:1px solid var(--line);padding-bottom:12px;width:100%}.eyebrow{font-size:13px;text-transform:uppercase;color:var(--green);font-weight:700;letter-spacing:0}.hero h1{font-size:64px;line-height:1.12;margin:18px 0}.hero p{font-size:19px;color:var(--fg);max-width:490px}.actions{display:flex;gap:14px;flex-wrap:wrap;margin-top:28px}.section{max-width:1200px;margin:auto;padding:72px 32px;border-bottom:1px solid var(--line)}.section h2{font-size:36px;line-height:1.25;margin:12px 0 20px}.intro{max-width:700px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px;margin-top:36px}.item{border-top:1px solid var(--line);padding-top:26px}.number{color:var(--green);font-size:14px;font-weight:700}.item h3{font-size:22px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;padding:28px 0}.metrics strong{display:block;font-size:38px;color:var(--green);font-family:Sora}.metrics span{color:var(--muted)}.plan{border:1px solid var(--line);background:var(--surface);border-radius:8px;padding:26px;box-shadow:var(--shadow)}.plan h3{font-size:20px;margin:0}.price{font-size:38px;font-weight:700;margin:26px 0 8px}.price small{font-size:14px;color:var(--muted)}.slots{color:var(--green)}.plan p{font-size:14px}.note{border-left:3px solid var(--green);padding:8px 22px;margin-top:30px}.platform-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.platform{background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:30px;min-height:230px;display:flex;flex-direction:column;align-items:flex-start}.platform img{width:72px;height:42px;object-fit:contain;filter:invert(1);margin-bottom:24px}.platform h3{margin:0 0 8px;font-size:22px}.platform p{font-size:14px;margin:6px 0 16px}.platform a{color:var(--green);margin-top:auto;font-weight:700}.badge{font-size:12px;color:var(--green);margin:4px 0}.pending .badge{color:var(--muted)}.platform svg{width:48px;height:42px;stroke:var(--fg);fill:none;margin-bottom:24px}.lead{padding:50px 0;max-width:780px}details{padding:22px 0;border-bottom:1px solid var(--line)}summary{font-weight:700;cursor:pointer}footer{max-width:1200px;margin:auto;padding:36px 32px;display:flex;gap:24px;justify-content:space-between;flex-wrap:wrap;color:var(--muted);font-size:13px}footer div{display:flex;gap:20px;flex-wrap:wrap}.contact{display:flex;gap:14px;flex-wrap:wrap;margin-top:24px}.contact a{color:var(--green);border-bottom:1px solid var(--line);padding:10px 0}
@media(max-width:760px){nav{padding:16px 20px;gap:16px;flex-wrap:wrap}nav div{gap:18px;font-size:13px;flex-wrap:wrap}.hero{min-height:560px}.hero>img{object-position:35% center}.hero .inner{padding:48px 22px;align-items:flex-end}.hero h1{font-size:44px}.hero p{font-size:17px}.section{padding:48px 22px}.section h2{font-size:30px}.grid,.platform-grid{grid-template-columns:1fr}.metrics{grid-template-columns:1fr;gap:26px}.price{font-size:34px}footer{padding:30px 22px}.actions .btn{flex:1;justify-content:center}}
@media(prefers-reduced-motion:no-preference){.btn{transition:transform .18s}.btn:hover{transform:translateY(-2px)}}
'''
css += pathlib.Path(__file__).with_name('modern.css').read_text()
css += pathlib.Path(__file__).with_name('trust-light.css').read_text()
logo='/site-assets/branding/logo.png?v=official-blue-1210-4'
nav=f'<header><nav><a href="/" aria-label="ZUI Player início"><img src="{logo}" alt="ZUI Player"></a><div><a href="/disponivel">Disponível</a><a href="/pool">Parceiros</a><a href="/pool#parceria" class="nav-contact">Fale com a gente ↗</a></div></nav></header>'
foot='<footer><span>© ZUI Player · Seu conteúdo. Seu player.</span><div><a href="/pool">Parcerias</a><a href="/disponivel">Plataformas</a><a href="/politica-de-privacidade">Privacidade</a><a href="/termos-de-uso">Termos de uso</a></div></footer>'
def page(title,desc,body):
 return f'<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{desc}"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:type" content="website"><meta name="twitter:card" content="summary_large_image"><style>{css}</style><script src="/partner-assets/contact.js?v=20261014" defer></script><script src="/partner-assets/platforms.js?v=20261014" defer></script></head><body>{nav}<main>{body}</main>{foot}</body></html>'
# Pricing comes from the deployed plan definition, not independent public constants.
plans=re.findall(r"\{id:'([^']+)',name:'([^']+)',slots:(\d+),monthly:(\d+|null)(?:,perSlot:([\d.]+))?\}",pathlib.Path('deploy/zui-pool/zui-pool.mjs').read_text())
cards=''
for id,name,slots,monthly,per in plans:
 price=('R$ '+f'{int(monthly):,}'.replace(',','.')) if monthly!='null' else 'R$ '+per.replace('.',',')
 unit='/mês' if monthly!='null' else '/vaga/mês'
 cards+=f'<article class="plan"><h3>{name}</h3><div class="price">{price} <small>{unit}</small></div><div class="slots">{int(slots):,} reproduções simultâneas</div>'.replace(f'{int(slots):,} reproduções','Ilimitado · cobrança por vaga' if slots=='0' else f'{int(slots):,}'.replace(',','.')+' reproduções')+f'<p>Gestão de servidores parceiros e acompanhamento de ocupação.</p><a href="#parceria">Consultar parceria →</a></article>'
pool='''<section class="hero"><img src="/partner-assets/pool-devices.jpg" width="1600" height="912" alt="Televisão, computador, tablet e celular com catálogos ilustrativos"><div class="inner"><div class="copy"><span class="eyebrow">Programa de parceiros</span><h1>ZUI Pool</h1><p>Uma visão clara da sua operação. Servidores, aparelhos e reproduções simultâneas, reunidos em um só painel.</p><div class="actions"><a class="btn primary" href="#parceria">Quero ser parceiro →</a><a class="btn" href="#como-funciona">Conhecer o Pool ↓</a></div></div></div></section>
<section class="section" id="como-funciona"><span class="eyebrow">Mais controle, menos complexidade</span><h2>O Pool acompanha quem está assistindo.</h2><p class="intro">Uma vaga representa uma reprodução simultânea nos servidores atribuídos ao parceiro. O vídeo continua indo do provedor para o aparelho: o ZUI organiza a operação, sem hospedar ou fornecer conteúdos.</p><div class="grid"><article class="item"><span class="number">01 / CONECTAR</span><h3>Seus servidores</h3><p>Servidores atribuídos pelo administrador ficam na sua área de parceiro, com os aparelhos vinculados a cada código.</p></article><article class="item"><span class="number">02 / ACOMPANHAR</span><h3>Sua ocupação</h3><p>Veja as reproduções em andamento, a ocupação por servidor e os picos diários da operação.</p></article><article class="item"><span class="number">03 / ADMINISTRAR</span><h3>Seu crescimento</h3><p>Troque DNS e migre suas listas com prévia, confirmação e histórico. Vagas extras podem ser atribuídas para eventos.</p></article></div><div class="metrics"><div><strong>80 · 90 · 100%</strong><span>Faixas de alerta de ocupação</span></div><div><strong>1 reprodução</strong><span>Uma vaga ocupada por aparelho reproduzindo</span></div><div><strong>Até 90 s</strong><span>Liberação da vaga sem resposta do aparelho</span></div></div><p class="note">Hoje o Pool é somente contagem: atingir o limite do plano não bloqueia ninguém. Navegar no aplicativo não ocupa vaga; a reprodução e a prévia ocupam.</p></section>
<section class="section" id="planos"><span class="eyebrow">Uma parceria para cada operação</span><h2>Planos ZUI Pool</h2><p>Capacidade e valores atualmente cadastrados no painel. Confirme as condições e a ativação da parceria com o atendimento.</p><div class="grid">'''+cards+'''</div></section><section class="section"><h2>Antes de começar</h2><details><summary>O Pool inclui canais, filmes ou séries?</summary><p>Não. O ZUI é apenas um reprodutor. Conteúdos e playlists são fornecidos pelo usuário ou por seu provedor, sob sua responsabilidade.</p></details><details><summary>A parceria muda a licença da TV?</summary><p>Não. O prazo da parceria controla a administração dos servidores delegados. A licença do aplicativo e a validade da playlist seguem suas próprias regras.</p></details><details><summary>O vídeo passa pelo ZUI?</summary><p>O Pool só acompanha a ocupação. Nas TVs, a reprodução segue a rota configurada no aplicativo e no servidor parceiro; o Pool não adiciona retransmissão.</p></details></section><section class="section" id="parceria"><span class="eyebrow">Vamos conversar</span><h2>Sua próxima parceria começa aqui.</h2><p class="intro">Fale com o atendimento para escolher o plano e cadastrar sua operação.</p><div class="contact" data-contacts><a href="/admin">Acessar meu painel →</a></div></section>'''
(out/'pool.html').write_text(page('ZUI Pool — Parcerias ZUI Player','Conheça o ZUI Pool: servidores parceiros, gestão de DNS e acompanhamento de reproduções simultâneas.',pool))
body='''<section class="platform-lead"><img src="/partner-assets/pool-devices.jpg" width="1600" height="912" alt="ZUI Player em diferentes telas"><div class="lead"><span class="eyebrow">Suas telas. Uma experiência ZUI.</span><h1>ZUI Player.<br>Escolha onde assistir.</h1><p>Seu player na tela que combina com você. Conheça as plataformas e encontre o aplicativo para o seu aparelho.</p><div class="actions"><a href="#plataformas" class="btn primary">Encontrar meu aparelho ↓</a><a href="/pool" class="btn">Seja parceiro ↗</a></div></div></section><section class="section" id="plataformas"><div class="section-heading"><div><span class="eyebrow">Conectado ao seu mundo</span><h2>Disponível para suas telas</h2></div><p>Instale pela loja ou consulte a instalação para o seu modelo.</p></div><nav class="platform-filters" aria-label="Filtrar plataformas"><a href="#plataformas" data-filter="all" aria-current="true">Todas as plataformas</a><a href="#plataformas" data-filter="available">Disponíveis</a><a href="#plataformas" data-filter="pending">Em breve</a></nav>'''
body+="<div id='zp-public-platforms' class='platform-grid' aria-live='polite'><p>Carregando plataformas…</p></div>"
body+='''<p class="note">Logos identificam as plataformas, sem indicar afiliação ou aprovação das marcas. O ZUI Player não vende, fornece nem hospeda conteúdo.</p></section><section class="section" id="instalacao"><span class="eyebrow">Instalação e compatibilidade</span><h2>Qual é o seu aparelho?</h2><p>Informe o modelo e a versão do sistema ao atendimento para receber a orientação correta.</p><div class="contact" data-contacts><a href="/minhas-listas">Gerenciar minhas playlists →</a></div></section>'''
(out/'disponivel.html').write_text(page('ZUI Player — Plataformas e instalação','Encontre o ZUI Player para computadores Windows, TVs e outras plataformas. Conheça as opções de instalação e o programa de parceiros.',body))
(out/'contact.js').write_text('''(()=>{fetch('/api/public/contacts').then(r=>{if(!r.ok)throw Error();return r.json()}).then(c=>{for(const box of document.querySelectorAll('[data-contacts]')){for(const [key,title] of [['whatsapp','WhatsApp ↗'],['telegram','Telegram ↗'],['email','E-mail ↗']]){const v=c[key];if(!v)continue;const a=document.createElement('a');a.textContent=title;a.href=key==='email'?'mailto:'+v:key==='telegram'?'https://t.me/'+v.replace(/^@/,''):'https://wa.me/'+v.replace(/\\D/g,'');a.rel='noopener';box.prepend(a)}}}).catch(()=>{})})();''')
(out/'platforms.js').write_text('''(()=>{const box=document.getElementById('zp-public-platforms');for(const a of document.querySelectorAll('header a'))if(a.getAttribute('href')===location.pathname)a.setAttribute('aria-current','page');if(!box)return;const labels={available:'Já disponível',guided:'Instalação orientada',pending:'Em confirmação',unavailable:'Indisponível'};const apply=filter=>{for(const a of document.querySelectorAll('[data-filter]'))a.setAttribute('aria-current',String(a.dataset.filter===filter));for(const card of box.querySelectorAll('[data-status]'))card.hidden=filter==='available'?!['available','guided'].includes(card.dataset.status):filter==='pending'?!['pending','unavailable'].includes(card.dataset.status):false;};for(const a of document.querySelectorAll('[data-filter]'))a.addEventListener('click',e=>{e.preventDefault();apply(a.dataset.filter)});fetch('/api/public/platforms').then(r=>{if(!r.ok)throw Error();return r.json()}).then(({platforms})=>{box.replaceChildren();for(const p of platforms){if(p.id==='web'||p.visible===false)continue;const card=document.createElement('article');card.className='platform '+(p.status==='available'?'available':'pending');card.dataset.status=p.status;const top=document.createElement('div');top.className='platform-top';const image=document.createElement('img');image.src='/partner-assets/platforms/'+p.icon+'.svg';image.alt='';image.width=52;image.height=38;const title=document.createElement('h3');title.textContent=p.name;const status=document.createElement('span');status.className='badge';status.textContent=labels[p.status]||'Em confirmação';const text=document.createElement('p');text.textContent=p.description;top.append(image,status);card.append(top,title,text);if(p.url&&p.status==='available'){const link=document.createElement('a');link.href=p.url;link.target='_blank';link.textContent=p.id==='windows'||p.id==='xbox'?'Obter na Microsoft Store':'Instalar aplicativo';link.rel='noopener noreferrer';const arrow=document.createElement('span');arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');link.append(arrow);card.append(link);}else if(p.status==='guided'){const link=document.createElement('a');link.href='#instalacao';link.textContent='Consultar instalação →';card.append(link);}box.append(card)}if(!box.children.length)box.textContent='Disponibilidade em atualização.';apply('all')}).catch(()=>{box.textContent='Não foi possível consultar a disponibilidade. Entre em contato com o atendimento.'})})();''')
print('built',out)
